mapper.select:
SELECT T.TEAM_NUM, T.TEAM_NAME, T.YEAR, T.TERM, T.USER_ID, T.INTRO, T.REG_DATE, U.NAME, U.SCHOOL, U.JUMIN
FROM TBL_TEAM T JOIN TBL_USER U ON T.USER_ID = U.USER_ID
WHERE T.TEAM_NUM = #{value}



SELECT *
FROM (
	SELECT
		ROWNUM AS RNUM,
		A.*
	FROM (
		SELECT T.TEAM_NUM, T.TEAM_NAME, T.YEAR, T.TERM, T.USER_ID, T.INTRO, T.REG_DATE, U.NAME
		FROM TBL_TEAM T JOIN TBL_USER U ON T.USER_ID = U.USER_ID
		WHERE 1 = 1



AND T.YEAR = #{year}



AND T.TERM = #{term}





		ORDER BY T.TEAM_NUM DESC
	) A
	WHERE ROWNUM <= #{pageEnd}
)
WHERE RNUM >= #{pageStart}
ORDER BY TEAM_NUM DESC


SELECT COUNT(*)
FROM TBL_TEAM T JOIN TBL_USER U ON T.USER_ID = U.USER_ID
WHERE 1 = 1


	AND T.YEAR = #{year}



	AND T.TERM = #{term}
